// The editor declarations: the two generated files in `.sail/` through which an editor resolves `sail` and
// `sail/intakes` to this machine's sail, and writeEditorDeclarations(), which writes the ones that are missing or stale.
import { afterEach, expect, test } from 'bun:test';
import {
  chmodSync,
  existsSync,
  mkdtempSync,
  readdirSync,
  readFileSync,
  rmSync,
  statSync,
  writeFileSync,
} from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { EditorWriteError, editorDeclarations, writeEditorDeclarations } from '../../src/engine/editor';
import { SDK_TYPES } from '../../src/engine/typecheck';

const dirs: string[] = [];
afterEach(() => {
  for (const dir of dirs.splice(0)) {
    chmodSync(dir, 0o755);
    rmSync(dir, { recursive: true, force: true });
  }
});

/** A fresh, empty directory that stands in for a `.sail/`. */
function sailDir(): string {
  const dir = mkdtempSync(join(tmpdir(), 'sail-editor-'));
  dirs.push(dir);
  return dir;
}

const HEADER = "// Generated by sail for this machine's editor. Not committed: sail check rewrites it.";

// biome-ignore format: TDD-PENDING TASK-008
test
  .skip // TDD-PENDING TASK-008
  ('each editor declaration is the header line and one export * from the path of the file SDK_TYPES names, without its .d.ts', () => {
  const declarations = editorDeclarations();
  expect(declarations.map((declaration) => declaration.name)).toEqual(['sail.d.ts', 'sail-intakes.d.ts']);
  const targets = declarations.map(({ text }) => {
    const [header, statement, last, ...more] = text.split('\n');
    expect([header, last, more]).toEqual([HEADER, '', []]);
    const specifier = /^export \* from (".*");$/.exec(statement ?? '')?.[1];
    return `${JSON.parse(specifier ?? '""')}.d.ts`;
  });
  expect(targets).toEqual([SDK_TYPES.sail[0] as string, SDK_TYPES['sail/intakes'][0] as string]);
  expect(targets.map((target) => existsSync(target))).toEqual([true, true]);
});

// biome-ignore format: TDD-PENDING TASK-008
test
  .skip // TDD-PENDING TASK-008
  ('writeEditorDeclarations writes both files into a .sail/ that has neither, returns them, and leaves nothing else there', () => {
  const dir = sailDir();
  expect(writeEditorDeclarations(dir)).toEqual([join(dir, 'sail.d.ts'), join(dir, 'sail-intakes.d.ts')]);
  expect(readdirSync(dir).sort()).toEqual(['sail-intakes.d.ts', 'sail.d.ts']);
  for (const { name, text } of editorDeclarations()) expect(readFileSync(join(dir, name), 'utf8')).toBe(text);
});

// biome-ignore format: TDD-PENDING TASK-008
test
  .skip // TDD-PENDING TASK-008
  ('it rewrites only the declaration that is missing or differs, and nothing when both are current', async () => {
  const dir = sailDir();
  const [sail, intakes] = [join(dir, 'sail.d.ts'), join(dir, 'sail-intakes.d.ts')];
  expect(writeEditorDeclarations(dir)).toEqual([sail, intakes]);
  const stamps = () => [statSync(sail).mtimeMs, statSync(intakes).mtimeMs];
  const first = stamps();
  await Bun.sleep(20);
  expect(writeEditorDeclarations(dir)).toEqual([]);
  expect(stamps()).toEqual(first);

  // One that names another machine's sail is stale.
  const current = readFileSync(intakes, 'utf8');
  writeFileSync(intakes, `${HEADER}\nexport * from "/somewhere/else/sail/types/intakes";\n`);
  expect(writeEditorDeclarations(dir)).toEqual([intakes]);
  expect(readFileSync(intakes, 'utf8')).toBe(current);
  expect(statSync(sail).mtimeMs).toBe(first[0] as number);

  rmSync(sail);
  expect(writeEditorDeclarations(dir)).toEqual([sail]);
  expect(readdirSync(dir).sort()).toEqual(['sail-intakes.d.ts', 'sail.d.ts']);
});

// biome-ignore format: TDD-PENDING TASK-008
test
  .skip // TDD-PENDING TASK-008
  .skipIf(process.getuid?.() === 0)(
  "a declaration that can't be written throws an EditorWriteError naming the file and why, and leaves no temporary file",
  () => {
    const dir = sailDir();
    chmodSync(dir, 0o555);
    let thrown: unknown;
    try {
      writeEditorDeclarations(dir);
    } catch (error) {
      thrown = error;
    }
    expect(thrown).toBeInstanceOf(EditorWriteError);
    expect((thrown as EditorWriteError).path).toBe(join(dir, 'sail.d.ts'));
    expect((thrown as EditorWriteError).message).toStartWith('EACCES');
    expect(readdirSync(dir)).toEqual([]);
  },
);
